/**
 * Browser Simulator - Mocks browser-side OpenTelemetry patterns
 */
const http = require('http');
const { initTelemetry, shutdown, emitLog, trace, propagation, context, SpanKind, SpanStatusCode } = require('./common/telemetry');

const PORT = process.env.PORT || 8090;
const FRONTEND_URL = process.env.FRONTEND_URL || 'http://localhost:8080';

const { tracer, meter, logger } = initTelemetry('browser-frontend');

// Metrics
const lcpHistogram = meter.createHistogram('lcp', { description: 'Largest Contentful Paint', unit: 'ms' });
const fcpHistogram = meter.createHistogram('fcp', { description: 'First Contentful Paint', unit: 'ms' });
const inpHistogram = meter.createHistogram('inp', { description: 'Interaction to Next Paint', unit: 'ms' });
const ttfbHistogram = meter.createHistogram('ttfb', { description: 'Time to First Byte', unit: 'ms' });
const clsGauge = meter.createObservableGauge('cls', { description: 'Cumulative Layout Shift' });
const userInteractionCounter = meter.createCounter('user_interactions', { unit: '{interactions}' });
const httpClientDuration = meter.createHistogram('http.client.request.duration', { unit: 's' });

let clsValue = 0;
let sessionId = `session-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

clsGauge.addCallback((result) => {
    result.observe(clsValue, { 'url.path_template': '/home' });
});

function recordWebVitals(pageUrl = '/home') {
    const span = tracer.startSpan('web-vitals', { kind: SpanKind.INTERNAL });
    const ctx = trace.setSpan(context.active(), span);

    const attrs = { 'url.full': `https://shop.example.com${pageUrl}`, 'page.title': 'OTel Demo Shop' };

    context.with(ctx, () => {
        const lcp = Math.random() * 3000 + 500;
        const fcp = Math.random() * 2000 + 200;
        const ttfb = Math.random() * 1000 + 100;
        const inp = Math.random() * 400 + 50;
        clsValue = Math.random() * 0.2;

        span.setAttributes({ 'web_vital.lcp': lcp, 'web_vital.fcp': fcp, 'web_vital.ttfb': ttfb, 'web_vital.inp': inp, 'web_vital.cls': clsValue });
        lcpHistogram.record(lcp, attrs);
        fcpHistogram.record(fcp, attrs);
        ttfbHistogram.record(ttfb, attrs);
        inpHistogram.record(inp, attrs);

        emitLog(logger, `WebVitals recorded for ${pageUrl}`, { 'url.path': pageUrl });
    });

    span.end();
}

function simulateUserInteraction(eventType, elementId) {
    const span = tracer.startSpan(`${eventType} - ${elementId}`, {
        kind: SpanKind.INTERNAL,
        attributes: { 'event.type': eventType, 'target.id': elementId, 'session.id': sessionId }
    });
    const ctx = trace.setSpan(context.active(), span);

    context.with(ctx, () => {
        userInteractionCounter.add(1, { 'event.type': eventType });
        emitLog(logger, `User interaction: ${eventType} on ${elementId}`, { 'event.type': eventType, 'target.id': elementId });
    });

    span.end();
}

function simulateFetch(url, method = 'GET') {
    return new Promise((resolve) => {
        const startTime = Date.now();
        const parentContext = context.active();

        const span = tracer.startSpan(`HTTP ${method}`, {
            kind: SpanKind.CLIENT,
            attributes: {
                'http.request.method': method,
                'url.full': `${FRONTEND_URL}${url}`,
                'url.path': url,
                'server.address': 'localhost',
                'server.port': 8080
            }
        }, parentContext);

        const spanContext = trace.setSpan(parentContext, span);
        const headers = {};
        propagation.inject(spanContext, headers);

        context.with(spanContext, () => {
            emitLog(logger, `HTTP ${method} ${url}`, { 'http.method': method, 'url.path': url });
        });

        const parsedUrl = new URL(`${FRONTEND_URL}${url}`);
        const req = http.request({
            hostname: parsedUrl.hostname,
            port: parsedUrl.port || 8080,
            path: parsedUrl.pathname + parsedUrl.search,
            method,
            headers,
            timeout: 30000,
        }, (res) => {
            let data = '';
            res.on('data', (chunk) => { data += chunk; });
            res.on('end', () => {
                const duration = (Date.now() - startTime) / 1000;
                span.setAttributes({ 'http.response.status_code': res.statusCode });
                if (res.statusCode >= 400) {
                    span.setStatus({ code: SpanStatusCode.ERROR, message: `HTTP ${res.statusCode}` });
                }
                span.end();
                httpClientDuration.record(duration, { 'http.request.method': method });
                resolve(data);
            });
        });

        req.on('error', (err) => {
            context.with(spanContext, () => {
                emitLog(logger, `HTTP request failed: ${url}`, { 'error': err.message, 'url.path': url }, 'ERROR');
            });
            span.recordException(err);
            span.setStatus({ code: SpanStatusCode.ERROR, message: err.message });
            span.end();
            resolve(null);
        });

        req.on('timeout', () => {
            span.setStatus({ code: SpanStatusCode.ERROR, message: 'timeout' });
            span.end();
            req.destroy();
            resolve(null);
        });

        if (method === 'POST') {
            req.write(JSON.stringify({ user_id: 'demo-user', products: ['123', '456'] }));
        }
        req.end();
    });
}

function simulateError(errorType, message) {
    const span = tracer.startSpan(errorType, { kind: SpanKind.INTERNAL });
    const ctx = trace.setSpan(context.active(), span);

    context.with(ctx, () => {
        span.setAttributes({ 'exception.type': errorType, 'exception.message': message });
        span.setStatus({ code: SpanStatusCode.ERROR, message });
        span.recordException(new Error(message));
        emitLog(logger, `${errorType}: ${message}`, { 'exception.type': errorType }, 'ERROR');
    });

    span.end();
}

async function runSimulation(count = 5) {
    console.log(`\nBrowser Simulator - ${count} page views\n`);
    const pages = ['/home', '/products', '/products/123', '/cart', '/checkout'];

    for (let i = 0; i < count; i++) {
        const page = pages[i % pages.length];
        console.log(`Page View ${i + 1}: ${page}`);

        const pageSpan = tracer.startSpan('page-session', {
            kind: SpanKind.INTERNAL,
            attributes: { 'page.url': page, 'session.id': sessionId }
        });
        const sessionCtx = trace.setSpan(context.active(), pageSpan);

        await context.with(sessionCtx, async () => {
            recordWebVitals(page);
            await sleep(300);

            if (page === '/home') simulateUserInteraction('click', 'browse-products-btn');
            else if (page === '/products') simulateUserInteraction('click', 'product-card');
            else if (page === '/products/123') simulateUserInteraction('click', 'add-to-cart-btn');
            else if (page === '/cart') simulateUserInteraction('click', 'checkout-btn');
            else if (page === '/checkout') simulateUserInteraction('submit', 'checkout-form');
            await sleep(200);

            await simulateFetch('/api/products', 'GET');
            await simulateFetch('/api/cart?user_id=demo-user', 'GET');
            await simulateFetch('/api/recommendations?productIds=123,456', 'GET');
            await simulateFetch('/api/checkout', 'POST');

            if (Math.random() < 0.1) {
                simulateError('window.onerror', 'Cannot read property "price" of undefined');
            }
        });

        pageSpan.setStatus({ code: 0 });
        pageSpan.end();
        await sleep(500);
    }
    console.log('\nBrowser Simulation Complete!\n');
}

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function runSingleIteration() {
    const page = '/checkout';

    const pageSpan = tracer.startSpan('page-session', {
        kind: SpanKind.INTERNAL,
        attributes: { 'page.url': page, 'session.id': sessionId }
    });
    const pageCtx = trace.setSpan(context.active(), pageSpan);

    try {
        await context.with(pageCtx, async () => {
            // Web vitals as child span
            const webVitalsSpan = tracer.startSpan('web-vitals', {
                kind: SpanKind.INTERNAL,
                attributes: { 'url.path': page }
            });
            webVitalsSpan.setAttributes({
                'web_vital.lcp': Math.random() * 3000 + 500,
                'web_vital.fcp': Math.random() * 2000 + 200,
                'web_vital.ttfb': Math.random() * 1000 + 100,
                'web_vital.inp': Math.random() * 400 + 50,
                'web_vital.cls': Math.random() * 0.2
            });
            webVitalsSpan.end();

            // User interaction - checkout form submit
            const interactionSpan = tracer.startSpan('submit - checkout-form', {
                kind: SpanKind.INTERNAL,
                attributes: { 'event.type': 'submit', 'target.id': 'checkout-form' }
            });
            userInteractionCounter.add(1, { 'event.type': 'submit' });
            interactionSpan.end();

            await Promise.all([
                simulateFetch('/api/products', 'GET'),
                simulateFetch('/api/cart?user_id=demo-user', 'GET'),
                simulateFetch('/api/recommendations?productIds=123,456', 'GET'),
                simulateFetch('/api/ads', 'GET')
            ]);

            await simulateFetch('/api/checkout', 'POST');
        });

        pageSpan.setStatus({ code: 0 });
    } catch (err) {
        pageSpan.setStatus({ code: SpanStatusCode.ERROR, message: err.message });
    } finally {
        pageSpan.end();
    }

    return { success: true, page };
}


// HTTP Server for load testing
const server = http.createServer(async (req, res) => {
    if (req.url === '/health') {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end('{"status":"ok"}');
        return;
    }
    if (req.url === '/trigger' || req.url === '/') {
        const result = await runSingleIteration();
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(result));
        return;
    }
    res.writeHead(404);
    res.end('Not found');
});

const rps = parseInt(process.env.RPS || '5');

server.listen(PORT, () => {
    console.log(`Browser Simulator listening on port ${PORT}`);
});

if (rps > 0) {
    const intervalMs = 1000 / rps;
    console.log(`Running continuously at ${rps} RPS (${intervalMs}ms interval)`);

    // Wait for services to start
    setTimeout(() => {
        setInterval(async () => {
            try {
                await runSingleIteration();
            } catch (err) {
                console.error('Iteration failed:', err.message);
            }
        }, intervalMs);
    }, 5000); // 5s startup delay
} else {
    console.log('RPS=0: HTTP server only (trigger via /trigger endpoint)');
}

process.on('SIGINT', async () => {
    console.log('Shutting down');
    await shutdown();
    process.exit(0);
});

// k6 Load Test Script for OpenTelemetry Demo
// Calls browser-simulator which creates proper traces with all instrumentation
//
// Modes:
//   Slow mode (2-3 req/s): k6 run load-test.js
//   Load test mode:        k6 run -e MODE=load load-test.js
//
// Install k6: brew install k6

import http from 'k6/http';
import { check, sleep } from 'k6';
import { randomIntBetween } from 'https://jslib.k6.io/k6-utils/1.2.0/index.js';
import { Trend, Counter, Rate } from 'k6/metrics';

// Custom metrics
const triggerDuration = new Trend('trigger_duration');
const errorRate = new Rate('errors');
const totalRequests = new Counter('total_requests');

// Mode selection: 'slow' (default) or 'load'
const MODE = __ENV.MODE || 'slow';

// Configuration based on mode
const scenarios = MODE === 'load' ? {
    load_test: {
        executor: 'shared-iterations',
        vus: 1000,
        iterations: 100000,
        maxDuration: '30m',
    },
} : {
    slow_test: {
        executor: 'constant-arrival-rate',
        rate: 3,              // 3 requests per second
        timeUnit: '1s',
        duration: '10m',      // Run for 10 minutes
        preAllocatedVUs: 2,   // Pre-allocate 2 VUs
        maxVUs: 5,            // Max 5 VUs if needed
    },
};

export const options = {
    scenarios,
    thresholds: {
        http_req_failed: ['rate<0.05'],     // Error rate < 5%
        http_req_duration: ['p(95)<15000'], // 95% requests under 15s
    },
};

// Browser-simulator URL (this creates proper traces with browser-frontend)
const BROWSER_SIM_URL = __ENV.BROWSER_SIM_URL || 'http://localhost:8090';

export default function () {
    // Call browser-simulator's /trigger endpoint
    // This triggers one full simulation with proper trace context:
    //   browser-frontend → frontend → product-catalog, cart, recommendation, checkout
    const res = http.get(`${BROWSER_SIM_URL}/trigger`, {
        tags: { name: 'BrowserSimulation' },
        timeout: '30s',
    });

    check(res, {
        'trigger status 200': (r) => r.status === 200,
        'has success': (r) => r.json('success') === true,
    });

    triggerDuration.add(res.timings.duration);
    totalRequests.add(1);
    errorRate.add(res.status !== 200);

    // Small random sleep between iterations
    sleep(randomIntBetween(0.05, 0.2));
}

export function setup() {
    console.log('========================================');
    console.log('OpenTelemetry Demo Load Test');
    console.log('========================================');
    console.log(`Mode: ${MODE === 'load' ? 'LOAD TEST (high volume)' : 'SLOW (3 req/s)'}`);
    console.log(`Target: ${BROWSER_SIM_URL}/trigger`);
    console.log('');
    console.log('Each trigger creates a full trace:');
    console.log('  browser-frontend (JS)');
    console.log('    → frontend (JS)');
    console.log('        → product-catalog (Go)');
    console.log('        → cart (Go) → Redis');
    console.log('        → recommendation (Python)');
    console.log('        → checkout (Go) → all services');
    console.log('========================================');
    if (MODE === 'slow') {
        console.log('Tip: Use -e MODE=load for high-volume load testing');
    }

    // Verify browser-simulator is reachable
    const healthRes = http.get(`${BROWSER_SIM_URL}/health`);
    if (healthRes.status !== 200) {
        console.error(`Browser-simulator not reachable! Status: ${healthRes.status}`);
        console.error('Make sure services are running: COUNT=0 docker-compose up');
    } else {
        console.log('Browser-simulator is healthy ✓');
    }
}

export function teardown(data) {
    console.log('');
    console.log('========================================');
    console.log('Load Test Complete!');
    console.log('========================================');
}

/**
 * Payment Service - Transaction processing
 */
const http = require('http');
const url = require('url');
const { randomUUID } = require('crypto');
const { initTelemetry, shutdown, emitLog, trace, propagation, context, SpanKind, SpanStatusCode } = require('./common/telemetry');

const PORT = process.env.PORT || 8081;
const { tracer, meter, logger } = initTelemetry('payment');

const transactionsCounter = meter.createCounter('app.payment.transactions', { unit: '{transactions}' });
const paymentLatency = meter.createHistogram('app.payment.latency', { unit: 'ms' });

const CARD_PREFIXES = { '4': 'visa', '5': 'mastercard', '3': 'amex', '6': 'discover' };
const LOYALTY_LEVELS = ['bronze', 'silver', 'gold', 'platinum'];

const server = http.createServer((req, res) => {
    const parsedUrl = url.parse(req.url, true);
    const ctx = propagation.extract(context.active(), req.headers);

    if (parsedUrl.pathname === '/charge' && req.method === 'POST') {
        handleCharge(req, res, ctx);
    } else {
        res.writeHead(404);
        res.end('{"error":"Not found"}');
    }
});

function handleCharge(req, res, parentCtx) {
    const start = Date.now();

    const span = tracer.startSpan('charge', {
        kind: SpanKind.SERVER,
        attributes: { 'rpc.system': 'grpc', 'rpc.service': 'oteldemo.PaymentService', 'rpc.method': 'Charge' },
    }, parentCtx);

    context.with(trace.setSpan(parentCtx, span), () => {
        try {
            const baggage = propagation.getBaggage(trace.setSpan(parentCtx, span));
            if (baggage) {
                const syntheticEntry = baggage.getEntry('synthetic_request');
                span.setAttribute('app.payment.charged', !(syntheticEntry && syntheticEntry.value === 'true'));
            } else {
                span.setAttribute('app.payment.charged', true);
            }

            const cardNumber = `4${Math.floor(Math.random() * 1e15).toString().padStart(15, '0')}`;
            const cardType = CARD_PREFIXES[cardNumber.charAt(0)] || 'unknown';
            const lastFour = cardNumber.slice(-4);
            const loyaltyLevel = LOYALTY_LEVELS[Math.floor(Math.random() * LOYALTY_LEVELS.length)];
            const amount = (Math.random() * 500 + 10).toFixed(2);
            const currency = ['USD', 'EUR', 'GBP', 'JPY'][Math.floor(Math.random() * 4)];
            const transactionId = randomUUID();

            span.setAttributes({
                'app.payment.card_type': cardType,
                'app.payment.card_valid': true,
                'app.payment.last_four': lastFour,
                'app.loyalty.level': loyaltyLevel,
                'app.payment.amount': parseFloat(amount),
                'app.payment.currency': currency,
                'app.payment.transaction.id': transactionId,
            });

            if (Math.random() < 0.05) {
                const error = new Error('Payment failed: insufficient funds');
                span.recordException(error);
                span.setStatus({ code: SpanStatusCode.ERROR, message: error.message });
                span.addEvent('payment_failed', { 'app.payment.failure_reason': 'insufficient_funds' });
                transactionsCounter.add(1, { currency, status: 'failed', card_type: cardType });
                res.writeHead(402);
                res.end(JSON.stringify({ error: error.message }));
            } else {
                span.addEvent('payment_successful', { 'app.payment.transaction.id': transactionId });
                transactionsCounter.add(1, { currency, status: 'success', card_type: cardType });
                emitLog(logger, `Payment successful: ${transactionId}`, { 'transaction.id': transactionId, 'amount': amount, 'currency': currency });
                res.writeHead(200, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ transaction_id: transactionId, amount, currency, card_type: cardType }));
            }

            paymentLatency.record(Date.now() - start, { card_type: cardType });
            span.end();
        } catch (err) {
            span.recordException(err);
            span.setStatus({ code: SpanStatusCode.ERROR, message: err.message });
            span.end();
            res.writeHead(500);
            res.end(JSON.stringify({ error: err.message }));
        }
    });
}

server.listen(PORT, () => console.log(`Payment Service listening on port ${PORT}`));
process.on('SIGINT', () => { shutdown(); process.exit(0); });

/**
 * Email Service - Order confirmation emails
 */
const http = require('http');
const url = require('url');
const { randomUUID } = require('crypto');
const { initTelemetry, shutdown, emitLog, trace, propagation, context, SpanKind } = require('./common/telemetry');

const PORT = process.env.PORT || 8088;
const { tracer, meter, logger } = initTelemetry('email');

const emailsCounter = meter.createCounter('app.email.sent', { unit: '{emails}' });
const emailLatency = meter.createHistogram('app.email.latency', { unit: 'ms' });

const server = http.createServer((req, res) => {
    const parsedUrl = url.parse(req.url, true);
    const ctx = propagation.extract(context.active(), req.headers);

    if (parsedUrl.pathname === '/send' && req.method === 'POST') {
        handleSendEmail(req, res, ctx, parsedUrl.query);
    } else {
        res.writeHead(404);
        res.end('{"error":"Not found"}');
    }
});

function handleSendEmail(req, res, parentCtx, query) {
    const start = Date.now();

    const span = tracer.startSpan('sendOrderConfirmation', {
        kind: SpanKind.SERVER,
        attributes: { 'rpc.system': 'grpc', 'rpc.service': 'oteldemo.EmailService', 'rpc.method': 'SendOrderConfirmation' },
    }, parentCtx);

    context.with(trace.setSpan(parentCtx, span), () => {
        try {
            const orderId = query.order_id || randomUUID();
            const userId = query.user_id || `user-${Math.floor(Math.random() * 10000)}`;
            const email = query.email || `${userId}@example.com`;

            span.setAttributes({
                'app.order.id': orderId,
                'app.user.id': userId,
                'app.email.recipient': email,
                'app.email.type': 'order_confirmation',
            });

            // Read baggage
            const baggage = propagation.getBaggage(trace.setSpan(parentCtx, span));
            if (baggage) {
                const sessionId = baggage.getEntry('session.id');
                if (sessionId) span.setAttribute('session.id', sessionId.value);
            }

            if (Math.random() < 0.02) {
                const error = new Error('SMTP connection failed');
                span.recordException(error);
                span.setStatus({ code: 2, message: error.message });
                span.addEvent('email_failed', { 'app.email.failure_reason': 'smtp_error' });
                emailsCounter.add(1, { type: 'order_confirmation', status: 'failed' });
                res.writeHead(500);
                res.end(JSON.stringify({ error: error.message }));
            } else {
                const messageId = `msg-${randomUUID().slice(0, 8)}`;
                span.setAttribute('app.email.message_id', messageId);
                span.addEvent('email_sent', { 'app.email.recipient': email, 'app.email.message_id': messageId });
                emailsCounter.add(1, { type: 'order_confirmation', status: 'sent' });
                emitLog(logger, `Email sent to ${email} for order ${orderId}`, { 'email.recipient': email, 'order.id': orderId });
                res.writeHead(200, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ success: true, message_id: messageId, recipient: email, order_id: orderId }));
            }

            emailLatency.record(Date.now() - start);
            span.end();
        } catch (err) {
            span.recordException(err);
            span.setStatus({ code: 2, message: err.message });
            span.end();
            res.writeHead(500);
            res.end(JSON.stringify({ error: err.message }));
        }
    });
}

server.listen(PORT, () => console.log(`Email Service listening on port ${PORT}`));
process.on('SIGINT', () => { shutdown(); process.exit(0); });

/**
 * Ad Service - Ad serving
 */
const http = require('http');
const url = require('url');
const { initTelemetry, shutdown, emitLog, trace, propagation, context, SpanKind } = require('./common/telemetry');

const PORT = process.env.PORT || 8087;
const { tracer, meter, logger } = initTelemetry('ad');

const adRequestsCounter = meter.createCounter('app.ads.ad_requests', { unit: '{requests}' });

const ADS_BY_CATEGORY = {
    accessories: [{ id: 'ad-1', text: 'Premium Sunglasses - 50% off!', url: '/products/OLJCESPC7Z' }],
    clothing: [{ id: 'ad-3', text: 'Summer Tank Tops', url: '/products/66VCHSJNUP' }],
    footwear: [{ id: 'ad-4', text: 'Designer Loafers', url: '/products/L9ECAV7KIM' }],
    home: [{ id: 'ad-5', text: 'Home Decor Essentials', url: '/products/0PUK6V6EV0' }],
    default: [{ id: 'ad-8', text: 'Shop Our Best Sellers!', url: '/' }],
};

const server = http.createServer((req, res) => {
    const parsedUrl = url.parse(req.url, true);
    const ctx = propagation.extract(context.active(), req.headers);

    if (parsedUrl.pathname === '/ads' || parsedUrl.pathname === '/') {
        handleGetAds(req, res, ctx, parsedUrl.query);
    } else {
        res.writeHead(404);
        res.end('{"error":"Not found"}');
    }
});

function handleGetAds(req, res, parentCtx, query) {
    const span = tracer.startSpan('getAds', { kind: SpanKind.SERVER }, parentCtx);

    context.with(trace.setSpan(parentCtx, span), () => {
        try {
            const contextKeys = query.context_keys ? query.context_keys.split(',') : [];
            span.setAttribute('app.ads.contextKeys', contextKeys.join(','));
            span.setAttribute('app.ads.contextKeys.count', contextKeys.length);

            // Read session from baggage
            const baggage = propagation.getBaggage(trace.setSpan(parentCtx, span));
            if (baggage) {
                const sessionId = baggage.getEntry('session.id');
                if (sessionId) span.setAttribute('session.id', sessionId.value);
            }

            let ads, requestType, responseType;
            const category = query.category || (contextKeys.length > 0 ? contextKeys[0] : null);

            if (category && ADS_BY_CATEGORY[category]) {
                ads = ADS_BY_CATEGORY[category];
                requestType = 'TARGETED';
                responseType = 'TARGETED';
            } else {
                const allAds = Object.values(ADS_BY_CATEGORY).flat();
                const count = Math.floor(Math.random() * 3) + 1;
                ads = allAds.sort(() => 0.5 - Math.random()).slice(0, count);
                requestType = 'NOT_TARGETED';
                responseType = 'RANDOM';
            }

            span.setAttributes({
                'app.ads.ad_request_type': requestType,
                'app.ads.ad_response_type': responseType,
                'app.ads.count': ads.length,
            });

            adRequestsCounter.add(1, { ad_request_type: requestType, ad_response_type: responseType });
            emitLog(logger, `Served ${ads.length} ${responseType.toLowerCase()} ads`, { 'ads.count': ads.length, 'ads.type': responseType });

